Mesh<Point, double> mesh;
std::map<RT::Cell_handle, std::size_t> cell_index;
std::vector<std::vector<std::size_t>> faces;

// Build cell index
std::size_t idx = 0;
for (auto it = rt.finite_cells_begin(); it != rt.finite_cells_end(); ++it) {
    cell_index[it] = idx++;
}

// Iterate over finite edges
for (auto it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    RT::Edge e = *it;
    if (is_small_edge(rt, e, threshold)) continue;

    RT::Cell_handle c1 = e.first;
    RT::Cell_handle c2 = c1->neighbor(e.second);

    if (rt.is_infinite(c1) || rt.is_infinite(c2)) continue;

    std::size_t i1 = cell_index.at(c1);
    std::size_t i2 = cell_index.at(c2);

    // Create face as polygon with two vertices (edge)
    faces.emplace_back(std::vector<std::size_t>{i1, i2});
}

// Build mesh
for (auto& face : faces) {
    std::vector<Point> polygon;
    for (std::size_t i : face) {
        auto it = rt.finite_cells_begin();
        std::advance(it, i);
        polygon.push_back(rt.dual(it));
    }
    mesh.add_face(polygon);
}

// Compute edge lengths
for (auto& face : mesh.faces) {
    for (std::size_t i = 0; i < face.vertices.size(); ++i) {
        std::size_t j = (i + 1) % face.vertices.size();
        double length = std::sqrt(CGAL::squared_distance(face.vertices[i], face.vertices[j]));
        face.attributes.push_back(length);
    }
}

return mesh;

